INSERT INTO `alertas_conf` (`id`, `tipo`, `dia`, `descripcion`, `mensaje`, `estado`) VALUES
(1, 'EMAIL', 7, 'Aviso por correo al cliente que tiene 7 dias más para retirar el equipo antes de cobrar bodegaje.', 'Estimado cliente.\n\nSe le informa que tiene 7 días para retirar su artículo en nuestras instalaciones. Después de ese tiempo, se iniciará el cobro por bodegaje. (500 colones x día)', 1),
(2, 'EMAIL', 14, 'Aviso por correo al cliente que tiene 15 dias más para retirar el equipo antes de que se deseche', 'Estimado cliente.\r \r Se le informa que a partir de este día comienza el cobro de Bodegaje por su artículo en Electrónica Torres. (500 colones x día)\r Cuenta con 15 días a partir de hoy para retirar su artículo. Después de ese período, se procederá con el desecho, tal y como lo estipula la Ley. \r \r Nota: Electrónica Torres esta comprometida con el cuido del medio ambiente, por lo tanto realizamos un tratamiento apropiado de los articulos desechados.', 1),
(3, 'INTERNO', 90, 'Equipo Debe Desecharse', 'Equipo Debe Desecharse. Los montos pagados por el cliente se deben facturar y los cargos excedentes se anularán.', 1);
